// Generated by build.mjs from src/challenge.js. Do not edit here.
// Monthly Challenge rules, shared by the app and the Netlify scores function so both
// pick the same 50 questions and compute the same score. Keep it dependency-free.
var CQC = (function () {
  var SIZE = 50, PACK_SLOTS = 10, PER_Q_MS = 20000, FAST_MS = 3000, MIN_MS = 1500;

  function hashInt(s) {
    var h = 2166136261;
    for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
  }
  function qid(moduleId, text) { return moduleId + ":" + hashInt(text).toString(36); }

  // Month in Irish time, e.g. "2026-10". The challenge set and the monthly table both key on this.
  function monthKey(date) {
    var p = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Dublin", year: "numeric", month: "2-digit" }).formatToParts(date || new Date());
    var y = "", m = "";
    p.forEach(function (x) { if (x.type === "year") y = x.value; if (x.type === "month") m = x.value; });
    return y + "-" + m;
  }
  function monthLabel(key) {
    var parts = key.split("-");
    return new Date(Date.UTC(+parts[0], +parts[1] - 1, 15)).toLocaleDateString("en-IE", { month: "long", year: "numeric", timeZone: "UTC" });
  }

  // modules: [{id, ids:[question ids]}] from the core bank (no STAR module).
  // packIds: question ids from this month's pack, if any.
  // Selection depends only on ids and the month, never on array order, so every device agrees.
  function pick(month, modules, packIds) {
    var rank = function (x) { return hashInt(month + "|" + x); };
    var byRank = function (arr) { return arr.slice().sort(function (a, b) { return rank(a) - rank(b) || (a < b ? -1 : 1); }); };
    var mods = modules.filter(function (m) { return m.ids.length; }).slice().sort(function (a, b) { return a.id < b.id ? -1 : 1; });
    var fromPack = byRank(packIds || []).slice(0, PACK_SLOTS);
    var chosen = [], seen = {};
    var add = function (id) { if (id && !seen[id]) { seen[id] = 1; chosen.push(id); } };
    mods.forEach(function (m) { add(byRank(m.ids)[0]); });
    var order = mods.slice().sort(function (a, b) { return rank("m:" + a.id) - rank("m:" + b.id); });
    for (var depth = 1; chosen.length < SIZE - fromPack.length && depth < 20; depth++) {
      for (var i = 0; i < order.length && chosen.length < SIZE - fromPack.length; i++) add(byRank(order[i].ids)[depth]);
    }
    fromPack.forEach(add);
    return chosen.slice(0, SIZE).sort(function (a, b) { return rank("o:" + a) - rank("o:" + b); });
  }

  // 100 for a right answer, up to +50 for speed (full bonus under 3 s, none at 20 s),
  // +10 per answer of running streak (capped at +50). Max 200 a question, 10,000 a run.
  function points(ms, streak) {
    var t = Math.max(ms, MIN_MS);
    var speed = t <= FAST_MS ? 50 : t >= PER_Q_MS ? 0 : Math.round(50 * (PER_Q_MS - t) / (PER_Q_MS - FAST_MS));
    return 100 + speed + 10 * Math.min(Math.max(streak - 1, 0), 5);
  }
  function score(results) {
    var total = 0, streak = 0, correct = 0, ms = 0;
    results.forEach(function (r) {
      var t = Math.min(Math.max(+r.ms || 0, 0), PER_Q_MS); ms += t;
      if (r.ok) { streak++; correct++; total += points(t, streak); } else streak = 0;
    });
    return { score: total, correct: correct, ms: ms };
  }
  return { SIZE: SIZE, PER_Q_MS: PER_Q_MS, MAX: SIZE * 200, hashInt: hashInt, qid: qid, monthKey: monthKey, monthLabel: monthLabel, pick: pick, points: points, score: score };
})();

export default CQC;
